INSERT INTO content_blocks (section, data) VALUES ('company', '{"name": "ООО «БелорецкДомСервис»", "short": "БелорецкДомСервис", "city": "Белорецк", "dispatchPhone": "8 (34792) 3-14-99", "dispatchPhoneHref": "tel:+73479231499", "officePhone": "8 (34792) 3-15-40", "officePhoneHref": "tel:+73479231540", "email": "domservis.b@mail.ru", "address": "453500, Республика Башкортостан, г. Белорецк, ул. Ленина, 68", "inn": "0256000000", "ogrn": "1120256000000"}'::jsonb);
INSERT INTO content_blocks (section, data) VALUES ('services', '{"heading": {"eyebrow": "Услуги", "title": "Что мы делаем каждый день", "description": "Полный цикл управления многоквартирным домом: от лампочки в подъезде до подготовки дома к отопительному сезону."}, "groups": [{"id": "maintenance", "label": "Содержание дома", "lead": "Ежедневная работа, из которой складывается «дом в порядке».", "items": [{"icon": "Brush", "title": "Уборка подъездов", "text": "Влажная уборка лестничных клеток по графику, мытьё окон и перил."}, {"icon": "Trees", "title": "Придомовая территория", "text": "Покос травы, вывоз снега, посыпка дорожек, уход за детскими площадками."}, {"icon": "Lightbulb", "title": "Освещение мест общего пользования", "text": "Замена ламп в подъездах, ремонт светильников и датчиков движения."}, {"icon": "DoorClosed", "title": "Подъездное оборудование", "text": "Доводчики, домофоны, почтовые ящики, окна и входные группы."}]}, {"id": "repair", "label": "Ремонт и инженерия", "lead": "Сантехника, электрика и кровля — плановые и срочные работы.", "items": [{"icon": "Wrench", "title": "Сантехнические работы", "text": "Стояки ХВС и ГВС, канализация, запорная арматура, устранение течей."}, {"icon": "Zap", "title": "Электромонтаж", "text": "Этажные щиты, вводные автоматы, внутридомовые сети до квартиры."}, {"icon": "Home", "title": "Кровля и фасад", "text": "Локальный ремонт кровли, межпанельные швы, козырьки над входами."}, {"icon": "Thermometer", "title": "Отопление", "text": "Промывка и опрессовка системы, регулировка, подготовка к зиме."}]}, {"id": "accounting", "label": "Начисления и учёт", "lead": "Прозрачные квитанции и понятные расчёты по каждому дому.", "items": [{"icon": "Receipt", "title": "Квитанции", "text": "Формирование единого платёжного документа и расшифровка строк."}, {"icon": "Gauge", "title": "Показания приборов учёта", "text": "Приём показаний ИПУ и ОДПУ, поверка общедомовых счётчиков."}, {"icon": "FileSpreadsheet", "title": "Отчёты по дому", "text": "Годовой отчёт о выполненных работах и расходовании средств."}, {"icon": "Scale", "title": "Работа с задолженностью", "text": "Сверка расчётов, рассрочка, досудебное урегулирование."}]}, {"id": "legal", "label": "Работа с собственниками", "lead": "Собрания, документы и вопросы, которые решает управляющая организация.", "items": [{"icon": "Users", "title": "Общие собрания", "text": "Подготовка, проведение и оформление протоколов ОСС."}, {"icon": "FileText", "title": "Справки и выписки", "text": "Выписка из лицевого счёта, справка о составе семьи, акты."}, {"icon": "ShieldCheck", "title": "Акты и осмотры", "text": "Комиссионные осмотры, акты о заливе и повреждении имущества."}, {"icon": "MessagesSquare", "title": "Обращения и жалобы", "text": "Регистрация обращений и ответ в установленные законом сроки."}]}]}'::jsonb);
INSERT INTO content_blocks (section, data) VALUES ('about', '{"heading": {"eyebrow": "О компании", "title": "Управляем домами, а не бумагами"}, "paragraphs": ["ООО «БелорецкДомСервис» — управляющая организация, которая обслуживает многоквартирные дома в Белорецке. Мы отвечаем за инженерные сети, подъезды, кровли и придомовую территорию: за всё, что находится за порогом квартиры и принадлежит собственникам вместе.", "Работа устроена просто: диспетчерская принимает заявку, мастер выезжает, а житель видит результат в отчёте по дому. Плановые работы согласовываем с советом дома, аварийные выполняем немедленно — в любое время суток."], "principles": [{"icon": "Clock", "title": "Заявка не теряется", "text": "Каждое обращение получает номер, и вы можете узнать статус по телефону диспетчерской."}, {"icon": "Eye", "title": "Понятные расходы", "text": "Отчёт по каждому дому: сколько собрали, на что потратили, что запланировано."}, {"icon": "HardHat", "title": "Свои бригады", "text": "Сантехники, электрики и кровельщики в штате — не ждём подрядчика неделями."}], "stats": [{"value": "84", "unit": "дома", "label": "в управлении по Белорецку"}, {"value": "12 400", "unit": "жильцов", "label": "обслуживаем ежедневно"}, {"value": "24/7", "unit": "", "label": "работает аварийная служба"}, {"value": "2 ч", "unit": "", "label": "средний выезд по аварии"}], "schedule": [["Понедельник — пятница", "08:00 — 17:00"], ["Обед", "12:00 — 13:00"], ["Приём директора", "вторник, 15:00 — 17:00"]], "scheduleNote": "Аварийные заявки принимаются круглосуточно, включая выходные и праздничные дни."}'::jsonb);
INSERT INTO content_blocks (section, data) VALUES ('contacts', '{"heading": {"eyebrow": "Контакты", "title": "Найти нас просто", "description": "Приходите в офис, звоните диспетчеру или пишите на почту — обращение зарегистрируем в любом случае."}, "schedule": [["Пн — Пт", "08:00 — 17:00"], ["Обед", "12:00 — 13:00"], ["Сб — Вс", "только аварийные заявки"]]}'::jsonb);
INSERT INTO content_blocks (section, data) VALUES ('disclosure', '{"heading": {"eyebrow": "Раскрытие информации", "title": "Всё открыто по 731-ПП", "description": "Управляющая организация обязана раскрывать информацию о своей работе. Мы публикуем документы в ГИС ЖКХ и дублируем их здесь — чтобы искать не пришлось."}, "gisLink": "https://dom.gosuslugi.ru", "sections": [{"id": "org", "title": "Общая информация об организации", "text": "Сведения об управляющей организации, реквизиты, лицензия, структура и контакты руководства.", "docs": [{"title": "Устав ООО «БелорецкДомСервис»", "url": ""}, {"title": "Лицензия на управление МКД", "url": ""}, {"title": "Свидетельство о постановке на налоговый учёт", "url": ""}, {"title": "Сведения о членстве в СРО и объединениях", "url": ""}]}, {"id": "houses", "title": "Перечень домов в управлении", "text": "Адреса многоквартирных домов, год постройки, этажность, площадь и характеристики общего имущества.", "docs": [{"title": "Реестр многоквартирных домов на 2026 год", "url": ""}, {"title": "Технические паспорта домов", "url": ""}, {"title": "Перечень домов, где расторгнут договор управления", "url": ""}]}, {"id": "contracts", "title": "Договоры управления", "text": "Типовой договор управления, перечень работ и услуг, порядок изменения условий обслуживания.", "docs": [{"title": "Типовой договор управления МКД", "url": ""}, {"title": "Перечень работ и услуг по содержанию общего имущества", "url": ""}, {"title": "Протоколы общих собраний собственников", "url": ""}]}, {"id": "reports", "title": "Отчёты и финансовая отчётность", "text": "Годовые отчёты о выполнении договора управления по каждому дому, бухгалтерская отчётность.", "docs": [{"title": "Годовой отчёт о выполнении договора управления за 2025 год", "url": ""}, {"title": "Бухгалтерский баланс за 2025 год", "url": ""}, {"title": "Отчёт о расходовании средств текущего ремонта", "url": ""}]}, {"id": "works", "title": "Выполняемые работы и планы", "text": "План работ по текущему ремонту, подготовка к отопительному сезону, графики уборки и осмотров.", "docs": [{"title": "План текущего ремонта на 2026 год", "url": ""}, {"title": "График подготовки домов к отопительному сезону", "url": ""}, {"title": "График санитарного содержания подъездов", "url": ""}]}]}'::jsonb);